Buzzer = 11
wholeNote = (60*4)/140
def setup():
    GPIO.setmode(Buzzer)
    GPIO.setup(Buzzer, GPIO.OUT)
    global Buzz
    Buzz = GPIO.PWM(Buzzer, 440)
    Buzz.start(50)
def destory():
    Buzz.stop()
    GPIO.output(Buzzer, 1)
    GPIO.cleanup()
def playSong(melody):
    for i in range(0, len(melody), 2):
        if(i+1 < len(melody)):
            divider = melody[i+1]
            noteDuration = 0
            if(divider > 0):
                noteDuration = wholeNote/divider
            else:
                divider *= -1.5
                noteDuration = wholeNote/divider
            Buzz.ChangeFrequency(melody[i])
            time.sleep(noteDuration * 0.9)
def getRandomSong():
    randNum = random.randint(0, 21)
    song = songs[randNum]
    return song
count = 0
if __name__ == '__main__':
    setup()
    try:
        while True:
            song = getRandomSong()
            playSong(song)
    except KeyboardInterrupt:
        destory()
